-- Replace the reward pool without deleting or reassigning member-owned gifts.
-- Idempotent: original keys remain stable; legacy catalogue numbers are reserved.
BEGIN;
LOCK TABLE public.virtual_gifts IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE prior_gift_inventory ON COMMIT DROP AS SELECT * FROM public.user_gift_inventory;
CREATE TEMP TABLE prior_gift_claims ON COMMIT DROP AS SELECT * FROM public.lucky_draw_claims;
UPDATE public.virtual_gifts SET reward_eligible=false,
 catalogue_number=CASE WHEN catalogue_number BETWEEN 1 AND 520 THEN catalogue_number+10000 ELSE catalogue_number END
 WHERE gift_key ~ '^gift-[0-9]+$';
-- Keep legacy rows readable so cabinet/history joins retain the original identity.
