 AS t(gift_key text,catalogue_number integer,name text,description text,court_name text,collection_type text)
ON CONFLICT (gift_key) DO UPDATE SET catalogue_number=EXCLUDED.catalogue_number,
 name=EXCLUDED.name,description=EXCLUDED.description,court_name=EXCLUDED.court_name,
 collection_type=EXCLUDED.collection_type,catalogue_status='catalogued',art_status='final',reward_eligible=true;
DO $verify$
BEGIN
 IF (SELECT count(*) FROM public.virtual_gifts WHERE reward_eligible AND catalogue_status='catalogued') <> 600 THEN
  RAISE EXCEPTION 'Expected exactly 600 eligible treasures';
 END IF;
 IF EXISTS ((SELECT * FROM public.user_gift_inventory EXCEPT SELECT * FROM prior_gift_inventory)
 UNION ALL (SELECT * FROM prior_gift_inventory EXCEPT SELECT * FROM public.user_gift_inventory)) THEN
  RAISE EXCEPTION 'Inventory changed unexpectedly';
 END IF;
 IF EXISTS ((SELECT * FROM public.lucky_draw_claims EXCEPT SELECT * FROM prior_gift_claims)
 UNION ALL (SELECT * FROM prior_gift_claims EXCEPT SELECT * FROM public.lucky_draw_claims)) THEN
  RAISE EXCEPTION 'Claim history changed unexpectedly';
 END IF;
END $verify$;
COMMIT;
